const request = $input.first().json.body ?? $input.first().json;
const message = String(request.message ?? '').trim();
const text = message.toLowerCase();
const available = Array.isArray(request.specialties) ? request.specialties : [];
const routes = [
  { specialty: 'Dermatologist', words: ['skin', 'rash', 'acne', 'eczema', 'mole', 'itch'] },
  { specialty: 'Gynecologist', words: ['period', 'menstrual', 'pregnan', 'gynec', 'ovarian', 'vaginal'] },
  { specialty: 'Pediatricians', words: ['child', 'children', 'baby', 'infant', 'toddler', 'pediatric'] },
  { specialty: 'Gastroenterologist', words: ['stomach', 'digest', 'abdominal', 'bowel', 'constipat', 'diarrh', 'heartburn'] },
  { specialty: 'Neurologist', words: ['headache', 'migraine', 'seizure', 'numbness', 'tingling', 'neurolog'] },
  { specialty: 'General physician', words: ['fever', 'cold', 'cough', 'fatigue', 'general', 'checkup', 'check-up'] },
];
const selected = routes.find(route => available.includes(route.specialty) && route.words.some(word => text.includes(word)));
let reply;
let recommendedSpecialties = [];
if (!message) {
  reply = 'Tell me what kind of care you are looking for, and I can help you find a relevant doctor specialty.';
} else if (selected) {
  recommendedSpecialties = [selected.specialty];
  reply = `For concerns like the one you described, you could consider speaking with a ${selected.specialty}. This is general directory guidance, not a diagnosis; a qualified clinician can assess your specific situation.`;
} else {
  const fallback = available.includes('General physician') ? 'General physician' : null;
  if (fallback) recommendedSpecialties = [fallback];
  reply = 'I could not confidently match that concern to a specialty in this directory. A general physician can often help you decide where to start. This tool does not diagnose conditions.';
}
return [{ json: { reply, recommendedSpecialties } }];
